style='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#0c1017;color:#eef2f8;font:16px/1.65 "Segoe UI",sans-serif}a{color:inherit}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid #afe67d;outline-offset:5px}header{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:16px max(24px,calc((100vw - 1160px)/2));border-bottom:1px solid #2c3444;background:#111721}header a{text-decoration:none;font-weight:650}header strong{letter-spacing:.09em;font-size:14px;color:#c9adff}main{max-width:1208px;margin:auto;padding:36px 24px 72px}.welcome{display:grid;grid-template-columns:1.45fr 1fr;gap:32px;align-items:center;padding-bottom:24px}.eyebrow{font-size:14px;letter-spacing:.12em;color:#afe67d;font-weight:700}h1{font-size:clamp(32px,5vw,50px);line-height:1.15;letter-spacing:-.025em;margin:10px 0 18px}h2{font-size:27px;margin:24px 0 8px}h3{font-size:20px}.muted{color:#aeb9cb}.community{background:#181d2b;border-left:3px solid #a879ff;padding:24px}.community h2{font-size:21px;margin:0 0 8px}.cta{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}.cta a{padding:11px 16px;text-decoration:none;background:#9e73ef;color:#fff;font-weight:700;border-radius:6px}.cta a.yt{background:#d83f4a}.socials{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}.socials a{font-size:14px;text-decoration:none;border-bottom:1px solid #8894a9}.classes{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:24px 0}.class-card{display:block;position:relative;background:#151c28;border:1px solid #303949;border-top:3px solid var(--class-color);text-decoration:none;padding:22px;transition:background .15s,transform .15s}.class-card:hover{background:#20293a;transform:translateY(-3px)}.class-card .number{font-size:14px;color:#a8b3c6}.class-card h3{font-size:26px;color:var(--class-color);margin:10px 0 8px}.class-card p{margin:0;color:#b7c2d4}.class-card .enter{display:block;margin-top:19px;font-weight:650;font-size:14px}.note{background:#171e29;border:1px solid #384355;padding:18px 22px;margin:24px 0}.note p{margin:5px 0}.quick{display:flex;flex-wrap:wrap;gap:12px;margin:24px 0}.quick a{border:1px solid #47546c;border-radius:5px;text-decoration:none;padding:10px 15px}footer{border-top:1px solid #333e50;padding-top:22px;font-size:14px;color:#adbbcf}footer a{color:#d2b6ff}.section{border-top:1px solid #47546c;margin-bottom:8px;scroll-margin-top:25px}.section>summary{cursor:pointer;list-style:none;font-weight:700;font-size:22px;padding:20px 0}.section>summary:before{content:"+ ";color:var(--class-color,#b597eb)}.section[open]>summary:before{content:"− "}.section-body{padding-bottom:24px}.entry{border:1px solid #3a465a;background:#151c28;margin:12px 0;scroll-margin-top:22px}.entry>summary{cursor:pointer;padding:17px 20px;font-weight:650;list-style:none}.entry>summary:before{content:"+ ";color:var(--class-color,#b597eb)}.entry[open]>summary:before{content:"− "}.detail-body{padding:0 20px 20px}.detail-body a,.section-body a{color:#cbb3ff;text-underline-offset:3px}.permalink{font-size:14px}.macro{background:#070b12;border:1px solid #334159;margin:16px 0}.copy{background:#afe67d;color:#0c1017;font-size:14px;font-weight:700;border:0;border-radius:4px;margin:12px;padding:10px 15px;cursor:pointer}pre{font:14px/1.7 Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere;padding:0 18px 18px;margin:0}.table-wrap{overflow:auto}table{width:100%;min-width:590px;border-collapse:collapse}td,th{padding:13px;text-align:left;vertical-align:top;border-bottom:1px solid #344158}th{background:#202b3b}.tag{display:inline-block;padding:3px 8px;color:#c1cad9;background:#202b3b;font-size:14px;border-radius:4px}li{margin-bottom:8px}.status{position:fixed;bottom:20px;right:20px;background:#afe67d;color:#0c1017;padding:10px 18px;border-radius:4px}.status:empty{display:none}@media(max-width:850px){.welcome{grid-template-columns:1fr}.classes{grid-template-columns:1fr 1fr}}@media(max-width:540px){main{padding:24px 18px 48px}.classes{grid-template-columns:1fr}.class-card{padding:18px}.community{padding:20px}header{padding:15px 18px;font-size:14px}.cta a{flex:1;text-align:center}.detail-body{padding:0 14px 16px}pre{font-size:13px}h1{font-size:34px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.class-card{transition:none}}'''
script='''function reveal(){const el=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(!el)return;for(let p=el;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;requestAnimationFrame(()=>el.scrollIntoView({block:'start'}))}window.addEventListener('hashchange',reveal);reveal();document.addEventListener('click',async e=>{const b=e.target.closest('.copy');if(!b)return;const c=b.parentElement.querySelector('code');try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(c.textContent);else{const t=document.createElement('textarea');t.value=c.textContent;t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();const ok=document.execCommand('copy');t.remove();if(!ok)throw Error('copy')}b.textContent='Copiada';setTimeout(()=>b.textContent='Copiar macro',2000)}catch{b.textContent='Selecciona y copia el texto';const s=window.getSelection(),r=document.createRange();r.selectNodeContents(c);s.removeAllRanges();s.addRange(r)}});'''
favicon="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='6' fill='%23151c28'/%3E%3Cpath d='M6 25V7h4l6 10 6-10h4v18h-4V14l-6 9-6-9v11z' fill='%23c9adff'/%3E%3C/svg%3E"
links=''.join(f'<a href="{url}" target="_blank" rel="noopener noreferrer">{label}</a>' for label,url in socials)
def head(title,description):return f'<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(description,quote=True)}"><link rel="icon" type="image/svg+xml" href="{favicon}"><style>{style}</style></head>'
def footer():return '<footer><strong>Comunidad de Muchamiel · WoW Forever</strong><p>Consulta: 9 de octubre de 2026. Beta nivel 30, 26 puntos con Legacy. Las propuestas de PvP necesitan práctica y las macros comprobación en el cliente.</p><div class="socials">'+links+'</div></footer>'
def common_header(home='./'):return '<header><strong>WOW FOREVER / MUCHAMIEL</strong><a href="'+home+'#clases">Elegir clase</a><a href="https://www.youtube.com/@muchamiel" target="_blank" rel="noopener noreferrer">YouTube</a></header>'
def build_home():
    cards=''.join(f'<a class="class-card" style="--class-color:{color}" href="{slug}/"><span class="number">{i:02d} / {english}</span><h3>{name}</h3><p>{desc}</p><span class="enter">Builds · Macros · Estrategias</span></a>' for i,(slug,name,english,color,desc) in enumerate(classes,1))
    welcome='''<section class="welcome"><div><p class="eyebrow">WOW FOREVER · NIVEL 30 · PVP</p><h1>¡Buenas, Muchamiel<br>y comunidad!</h1><p class="muted">Vengas de Twitch, YouTube, Kick o estés descubriendo el canal: bienvenido. Elige tu clase y prepara tus duelos, BGs y aventuras por Azeroth.</p></div><aside class="community"><h2>Nos vemos en el directo</h2><p>Si la guía te ayuda, apoya a Muchamiel: sigue los directos, suscríbete al canal y comparte tus pruebas con la comunidad.</p><div class="cta"><a href="https://www.twitch.tv/muchamiel" target="_blank" rel="noopener noreferrer">Seguir en Twitch</a><a class="yt" href="https://www.youtube.com/@muchamiel" target="_blank" rel="noopener noreferrer">Suscribirse en YouTube</a></div><div class="socials">'''+links+'''</div></aside></section><section id="clases"><h2>¿Qué clase juegas?</h2><p class="muted">Macros en inglés, explicaciones en español. Entra directamente a la guía que quieras.</p><div class="classes">'''+cards+'''</div></section><div class="note"><strong>Menos clics. Más atención al combate.</strong><p>Las macros ayudan a controlar objetivos, aliados, mascotas y defensas con menos pasos. No deciden por ti, no eliminan los tiempos de reutilización y no activan habilidades que aún no has aprendido.</p></div><div class="quick"><a href="warlock/#reglas">Reglas del torneo</a><a href="comunes/">Macros comunes y raciales</a><a href="warlock/#duelos">El brujo de Muchamiel</a></div>'''
    welcome=welcome.replace('<h1>¡Buenas, Muchamiel<br>y comunidad!</h1>', '<h1>WoW Forever</h1><h2>¡Buenas, Muchamiel y comunidad!</h2>')
    goals='''<section class="note" aria-label="Metas de la comunidad"><h2>SORTEO · 1 AÑO DE WOW</h2><p><strong>1.837 / 2.000 suscripciones</strong> · ¡Quedan 163 para llegar a 2k!</p><progress value="1837" max="2000" style="width:100%;accent-color:#a879ff" aria-label="1837 de 2000 suscripciones">91,85%</progress><p>Ayuda a Muchamiel a llegar a <strong>100.000 en YouTube</strong>. Si disfrutas sus vídeos y directos, suscríbete y comparte el canal.</p><div class="cta"><a href="https://www.twitch.tv/muchamiel" target="_blank" rel="noopener noreferrer">Apoyar en Twitch</a><a class="yt" href="https://www.youtube.com/@muchamiel" target="_blank" rel="noopener noreferrer">Rumbo a 100k en YouTube</a></div><p class="muted">Cifra facilitada por la comunidad el 9/10/2026; no se actualiza en directo. Consulta las condiciones y la vigencia del sorteo en el canal.</p></section><section class="note"><strong>Forever también se juega en directo</strong><p>Preparación de PvP, pruebas de clases y aventuras con la comunidad. Encuentra los vídeos y anuncios de Muchamiel en sus canales oficiales.</p><div class="quick"><a href="https://kick.com/muchamiel/videos" target="_blank" rel="noopener noreferrer">Ver directos anteriores</a><a href="https://www.youtube.com/@muchamiel/videos" target="_blank" rel="noopener noreferrer">Vídeos de YouTube</a></div></section>'''
    welcome=welcome.replace('<div class="note"><strong>Menos clics.',goals+'<div class="note"><strong>Menos clics.')
    (dist/'index.html').write_text(head('WoW Forever | Clases, builds y macros · Muchamiel','Guías PvP de las nueve clases de WoW Forever: nivel 30, builds de 26 puntos, macros, duelos, BGs y mundo abierto.')+'<body>'+common_header()+'<main>'+welcome+footer()+'</main></body></html>',encoding='utf-8')

if __name__=='__main__':
    # Preserve the completed Warlock guide before making the class selector the root.
    warlock=dist/'warlock';warlock.mkdir(exist_ok=True)
    src=dist/'index.html'
    if 'id="duelos"' in src.read_text(encoding='utf-8'):
        page=src.read_text(encoding='utf-8')
        page=page.replace('<header><strong>BRUJO / FOREVER</strong>', '<header><a href="../">Elegir clase</a><strong>BRUJO / FOREVER</strong>')
        (warlock/'index.html').write_text(page,encoding='utf-8')
    build_home()
    print('Selector de nueve clases y bienvenida a la comunidad preparados.')
